// --- widget.h ---
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor is declared, but not defined inline

    // Support for move operations also requires out-of-line definitions
    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

private:
    struct Impl; // Forward declaration of implementation class
    std::unique_ptr<Impl> pImpl;
};

// --- widget.cpp ---
#include "widget.h"
#include <string>
#include <vector>

// Full definition of implementation class
struct Widget::Impl {
    std::string name;
    std::vector<int> data;
};

// Constructor definition
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}

// Destructor definition - compiler generates unique_ptr destruction code here
// where Widget::Impl is a complete type.
Widget::~Widget() = default;

// Move operations must also be defined here
Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;

// --- main.cpp ---
// #include "widget.h"
// int main() {
//     Widget w; // Compiles successfully because of the out-of-line destructor
//     return 0;
// }
